import { useEffect, useId, useState, type FormEvent } from 'react';
import {
  fetchThreadPage,
  pageCount,
  sanitizeSearch,
  type ThreadPage,
} from '../../lib/threads';
import { type MemberProfile } from '../../lib/session';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * Pantalla MSG-01 · Lista de Hilos.
 *
 * Es LA PANTALLA, no un componente de presentación: importa `MemberProfile` de
 * `../../lib/session`, llama a `fetchThreadPage` con `profile.orgId` y posee el
 * estado de búsqueda y de página.
 *
 * `now` es inyectable para que los tests no dependan del reloj; por defecto es
 * `new Date()`.
 *
 * `onOpenThread` es F-118: el shell lo pasa desde `App.tsx` (cableado después
 * de escribirse esta tarea) para que el repo compile, y aquí se ignora a
 * propósito — MSG-02 no existía cuando se escribió esta tarea y abrir un hilo
 * no lleva a ningún sitio.
 *
 * El aviso brass de passphrase del mock no se pinta: en el MVP las claves viven
 * en memoria de sesión y no hay frase de seguridad que introducir (CLAUDE.md
 * §4; Plan §9 'Fuera'). La vista previa es siempre metadatos (spec §7), así
 * que no hay nada que ocultar.
 */

interface MessagesProps {
  profile: MemberProfile;
  now?: Date;
  onOpenThread?: (threadId: string) => void;
}

/**
 * F-128: el aviso enseña el error de verdad, no un «algo falló» genérico.
 * PostgREST rechaza con un objeto plano `{ code, message }`; `String(e)` daría
 * `[object Object]` y `e.message` daría `undefined`, así que se extraen `code`
 * y/o `message` cuando existen y se pintan junto a la frase para humanos.
 */
function formatError(e: unknown): string {
  const base = 'No se pudieron cargar los hilos.';
  if (e instanceof Error) {
    return e.message ? `${base} ${e.message}` : base;
  }
  if (typeof e === 'object' && e !== null) {
    const rec = e as Record<string, unknown>;
    const code = typeof rec.code === 'string' && rec.code ? rec.code : '';
    const message = typeof rec.message === 'string' && rec.message ? rec.message : '';
    const detail = [code, message].filter(Boolean).join(' — ');
    return detail ? `${base} ${detail}` : base;
  }
  const str = String(e);
  return str ? `${base} ${str}` : base;
}

/**
 * F-024: los números van por Intl, nunca a mano. `useGrouping: false` es lo que
 * hace que 1247 salga como «1247» y no como el «1.247» del mock.
 */
const countFormat = new Intl.NumberFormat('es-ES', { useGrouping: false });

function formatCount(n: number): string {
  return countFormat.format(n);
}

function threadCountLabel(count: number): string {
  const n = formatCount(count);
  return count === 1 ? `${n} hilo` : `${n} hilos`;
}

/** Ventana de páginas alrededor de la actual, para no pintar 30 botones. */
function pageNumbers(current: number, total: number): number[] {
  const start = Math.max(1, Math.min(current - 2, total - 4));
  const end = Math.min(total, start + 4);
  const out: number[] = [];
  for (let i = start; i <= end; i += 1) out.push(i);
  return out;
}

export function Messages({ profile, now = new Date(), onOpenThread }: MessagesProps) {
  // F-118: onOpenThread se recibe para que App.tsx compile y se ignora.
  void onOpenThread;

  const newContactNoteId = useId();

  const [draft, setDraft] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [data, setData] = useState<ThreadPage | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((result) => {
        if (cancelled) return;
        setData(result);
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        setData(null);
        setError(formatError(e));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [profile.orgId, search, page]);

  function handleSearchSubmit(e: FormEvent) {
    e.preventDefault();
    setSearch(sanitizeSearch(draft));
    setPage(1);
  }

  const totalPages = pageCount(data?.total ?? 0);

  return (
    <div className={styles.screen}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a
        extremo.
      </p>

      <div className={styles.actionsBar}>
        <form className={styles.searchWrap} role="search" onSubmit={handleSearchSubmit}>
          <i className="ti ti-search" aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
          />
        </form>
        <div className={styles.newContactWrap}>
          <button
            type="button"
            className={styles.newContactBtn}
            disabled
            aria-describedby={newContactNoteId}
            title="El Directorio queda fuera del MVP"
          >
            <i className="ti ti-address-book" aria-hidden="true" />
            Nuevo contacto
          </button>
          <span id={newContactNoteId} className={styles.outOfScopeNote}>
            El Directorio queda fuera del MVP
          </span>
        </div>
        {data && (
          <span className={styles.threadCount}>
            {threadCountLabel(data.total)} · Página {formatCount(page)} de{' '}
            {formatCount(totalPages)}
          </span>
        )}
      </div>

      {loading ? (
        <div className={styles.loading} role="status">
          Cargando hilos…
        </div>
      ) : error ? (
        <div className={styles.error} role="alert">
          {error}
        </div>
      ) : (
        <>
          {/* F-118: MSG-02 no existe; abrir un hilo no lleva a ningún sitio por ahora. */}
          <ThreadList threads={data?.threads ?? []} now={now} onOpen={() => {}} />
          {totalPages > 1 && (
            <div className={styles.pagination}>
              <button
                type="button"
                className={`${styles.pageBtn} ${styles.pageCtrl}`}
                disabled={page <= 1}
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                aria-label="Página anterior"
              >
                ‹
              </button>
              {pageNumbers(page, totalPages).map((n) => (
                <button
                  key={n}
                  type="button"
                  className={n === page ? `${styles.pageBtn} ${styles.pageActive}` : styles.pageBtn}
                  aria-current={n === page ? 'page' : undefined}
                  onClick={() => setPage(n)}
                >
                  {formatCount(n)}
                </button>
              ))}
              <button
                type="button"
                className={`${styles.pageBtn} ${styles.pageCtrl}`}
                disabled={page >= totalPages}
                onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                aria-label="Página siguiente"
              >
                ›
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

