  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  font-size: 12px;
  color: var(--bw-text-secondary);
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stateBadge {
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: var(--bw-radius);
  white-space: nowrap;
  flex-shrink: 0;
}

/* ABIERTO — gris acero */
.stateNeutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

/* CON CONSULTA PENDIENTE — azul calibración.
   El borde del aprobado es rgba(37,99,235,.2); --bw-chip-active-border (.3)
   es el token azul más cercano. */
.stateInfo {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

/* CON OFERTA PENDIENTE — ámbar */
.stateWarn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

/* ACUERDO ALCANZADO — verde */
.stateSuccess {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

/* CERRADO SIN ACUERDO — gris, tachado, solo lectura */
.stateClosed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

/* Estado vacío (spec §6) */
.empty {
  padding: 40px 24px;
  text-align: center;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
}

.emptyIcon {
  font-size: 28px;
  color: var(--bw-input-placeholder);
  margin-bottom: 12px;
}

.emptyText {
  font-size: var(--bw-size-body);
  color: var(--bw-input-text);
  line-height: 1.5;
  max-width: 420px;
  margin: 0 auto 8px;
}

.emptyNote {
  font-size: var(--bw-size-label);
  color: var(--bw-text-secondary);
  margin-bottom: 16px;
}

.emptyBtn {
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  color: var(--bw-cold-white);
  background: var(--bw-calibration-blue);
  font-size: var(--bw-size-input);
  font-weight: 500;
  font-family: var(--bw-font-body);
}

/* F-023 e: DIR-01 no está en el alcance del MVP. El botón se pinta apagado y
   el motivo queda visible en .emptyNote. */
.emptyBtn:disabled {
  background: var(--bw-hint-steel);
  color: var(--bw-steel-mist);
  cursor: not-allowed;
}

