import { useId } from 'react';
import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01, presentacional.
 *
 * Pinta las filas que recibe en el orden que las recibe — el orden es del
 * servidor (`last_item_at` descendente) — y al abrir avisa con el ID del hilo,
 * no con el objeto. No carga datos ni pagina.
 *
 * Con `threads` vacío enseña el estado vacío de la spec §6, con el botón
 * `Ir al Directorio` apagado porque DIR-01 no está en el alcance del MVP
 * (F-023 e) y el motivo visible.
 */

const TONE_CLASS: Record<StateTone, string> = {
  neutral: styles.stateNeutral!,
  info: styles.stateInfo!,
  warn: styles.stateWarn!,
  success: styles.stateSuccess!,
  closed: styles.stateClosed!,
};

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  /** Se avisa con el ID del hilo, no con el objeto. */
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  const emptyNoteId = useId();

  if (threads.length === 0) {
    return (
      <div className={styles.empty}>
        <div className={styles.emptyIcon} aria-hidden="true">
          <i className="ti ti-messages" />
        </div>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras
          organizaciones.
        </p>
        <p id={emptyNoteId} className={styles.emptyNote}>
          El Directorio queda fuera del MVP
        </p>
        <button
          type="button"
          className={styles.emptyBtn}
          disabled
          aria-describedby={emptyNoteId}
          title="El Directorio queda fuera del MVP"
        >
          Ir al Directorio
        </button>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => {
        const tone = stateTone(thread.state);
        return (
          <li
            key={thread.id}
            role="button"
            tabIndex={0}
            className={styles.row}
            onClick={() => onOpen(thread.id)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onOpen(thread.id);
              }
            }}
            aria-label={`Hilo con ${thread.counterpartyName}`}
          >
            <div className={styles.topRow}>
              <span className={styles.orgName}>{thread.counterpartyName}</span>
              {thread.counterpartyCountry ? (
                <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
              ) : null}
            </div>
            <div className={styles.tsRow}>
              <span className={styles.timestamp}>{relativeTime(thread.lastItemAt, now)}</span>
            </div>
            <div className={styles.bottomRow}>
              <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
              <span className={`${styles.stateBadge} ${TONE_CLASS[tone]}`}>{thread.state}</span>
            </div>
            <div />
          </li>
        );
      })}
    </ul>
  );
}
